const g = (name) => { try { return $(name).item.json.choices[0].message.content; } catch (e) { return ''; } };
const data = $('Preparar fonte').item.json.data;
const transcricao = $('Preparar fonte').item.json.transcricao;
const system = `Você é o Editor-Chefe. Recebe a saída de quatro especialistas (em JSON) e a transcrição original, e monta a nota final em Markdown. Você não reinterpreta a fonte, apenas organiza o que os especialistas entregaram. Escreva em português. Monte a nota exatamente neste formato:
---
tipo: reuniao
data: [DATA]
participantes: [participantes do Sumarizador]
tags: [reuniao, mais as tags_sugeridas]
status: destilada
---

# 🎙️ [titulo]

> [!info] Resumo em 1 linha
> [resumo_uma_linha]

## ✅ Action items
- [ ] [tarefa] — [responsavel] (quando responsavel for null, termine a linha logo após a tarefa, sem escrever o traço nem espaço)

## 🧭 Decisões tomadas
- [cada decisão]

## 🔑 Pontos-chave (3 a 5)
- [cada ponto_chave]

## 🔗 Relacionado
- [cada link como wikilink entre colchetes duplos]

---

> [!note]- 📄 Transcript bruto — clique para expandir
> [a transcrição inteira]

Regras: se uma lista vier vazia, escreva - (nada registrado); não crie itens que não vieram dos especialistas; preserve a transcrição inteira; devolva somente a nota.`;
const user = `DATA: ${data}

SUMARIZADOR: ${g('Sumarizador')}

ACTION ITEMS: ${g('Caçador de Action Items')}

DECISOES: ${g('Rastreador de Decisões')}

BIBLIOTECARIO: ${g('Bibliotecário')}

TRANSCRICAO:
${transcricao}`;
return [{ json: { system, user } }];

const md = $('Editor-Chefe').item.json.choices[0].message.content;
const permitidas = ['00 - Caixa de Entrada','01 - Projetos','02 - Áreas','03 - Recursos','04 - Arquivos'];
let folder = ($json.choices && $json.choices[0] && $json.choices[0].message ? $json.choices[0].message.content : '').trim();
folder = folder.replace(/^["'\s]+|["'.\s]+$/g, '').trim();
if (!permitidas.includes(folder)) { folder = '00 - Caixa de Entrada'; }
const m = md.match(/^#\s+(.+)$/m);
let titulo = (m ? m[1] : 'nota').replace(/[^\p{L}\p{N} \-]/gu, '').trim();
const slug = titulo.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 60) || 'nota';
const data = $('Preparar fonte').item.json.data;
const filename = `${data} - ${slug}.md`;
let conteudo = md;
if (!/\norigem:/.test(conteudo)) { conteudo = conteudo.replace('status: destilada', 'status: destilada\norigem: workshop-second-brain'); }
const contentB64 = Buffer.from(conteudo, 'utf8').toString('base64');
const owner = 'yagosamu';
const repo = 'second-brain-vault';
const path = `${folder}/${filename}`;
const pathUrl = path.split('/').map(encodeURIComponent).join('/');
return [{ json: { owner, repo, path, pathUrl, filename, folder, contentB64, commitMessage: `nota: ${titulo}` } }];

let sha = undefined;
let existing = '';
try {
  const r = $('Ler log').item.json;
  if (r && typeof r.content === 'string') { existing = Buffer.from(r.content, 'base64').toString('utf8'); sha = r.sha; }
} catch (e) {}
const data = $('Preparar fonte').item.json.data;
const titulo = String($('Preparar arquivo').item.json.commitMessage || '').replace(/^nota:\s*/, '');
const linha = `## [${data}] ingest | ${titulo} — via workshop-second-brain`;
const header = '# 📜 log.md — Second Brain\n\nRegistro append-only das notas ingeridas.\n\n---\n';
const base = (existing && existing.trim().length) ? existing.replace(/\s*$/, '') : header;
const novo = base + '\n' + linha + '\n';
const contentB64 = Buffer.from(novo, 'utf8').toString('base64');
const owner = $('Preparar arquivo').item.json.owner;
const repo = $('Preparar arquivo').item.json.repo;
const out = { owner, repo, contentB64, message: `log: ${titulo}` };
if (sha) { out.sha = sha; }
return [{ json: out }];
